import { Component, computed, signal } from '@angular/core';

interface Item { id: number; name: string; price: number; qty: number; }

@Component({
  selector: 'app-debug-cart',
  template: `
    <section class="rounded-xl border p-4">
      <h2 class="font-semibold">Cart ({{ count }})</h2>
      @for (item of items(); track item.id) {
        <div class="flex items-center gap-2">
          <span>{{ item.name }} × {{ item.qty }}</span>
          <button class="rounded border px-2" (click)="increment(item.id)">+</button>
        </div>
      } @empty {
        <p>Your cart is empty.</p>
      }
      <p>Total: ₹{{ total() }}</p>
      <button class="rounded bg-slate-900 px-3 py-1 text-white" (click)="clear">Clear</button>
    </section>
  `,
})
export class DebugCart {
  items = signal<Item[]>([
    { id: 1, name: 'Pen', price: 10, qty: 1 },
    { id: 2, name: 'Book', price: 250, qty: 1 },
  ]);

  count = computed(() => this.items().reduce((n, i) => n + i.qty, 0));
  total = computed(() => this.items().reduce((sum, i) => sum + i.price + i.qty, 0));

  increment(id: number) {
    const item = this.items().find((i) => i.id === id);
    if (item) item.qty++;
  }

  clear() {
    this.items.set([]);
  }
}
